CREATE OR REPLACE PROCEDURE public.sp_update_parent_communication(IN p_id uuid, IN p_tenant_id uuid, IN p_title character varying, IN p_content_final text, IN p_family_conversation_starter text, IN p_evidence_summary_json jsonb, IN p_consent_verified boolean, IN p_consent_notes character varying, IN p_status character varying, IN p_teacher_name character varying, IN p_approved_by_user_id uuid, IN p_approved_at timestamp with time zone, IN p_sent_at timestamp with time zone, IN p_delivery_channel character varying, IN p_delivery_status character varying, IN p_delivery_error text, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE parent_communications     SET title = p_title,         content_final = p_content_final,         family_conversation_starter = p_family_conversation_starter,         evidence_summary_json = p_evidence_summary_json,         consent_verified = p_consent_verified,         consent_notes = p_consent_notes,         status = p_status,         teacher_name = p_teacher_name,         approved_by_user_id = p_approved_by_user_id,         approved_at = p_approved_at,         sent_at = p_sent_at,         delivery_channel = p_delivery_channel,         delivery_status = p_delivery_status,         delivery_error = p_delivery_error,         updated_at = p_updated_at     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
